import{_ as e,o as a,c as i,an as t}from"./chunks/framework.GScxl26e.js";const k=JSON.parse('{"title":"The forms a lowering can take","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/tutorials/lowering-forms.md","filePath":"getting-started/tutorials/lowering-forms.md","lastUpdated":null}'),n={name:"getting-started/tutorials/lowering-forms.md"};function l(h,s,o,d,p,r){return a(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="The-forms-a-lowering-can-take" tabindex="-1">The forms a lowering can take <a class="header-anchor" href="#The-forms-a-lowering-can-take" aria-label="Permalink to &quot;The forms a lowering can take {#The-forms-a-lowering-can-take}&quot;">​</a></h1><p><code>lower</code> returns one of three representations, chosen from the value of the distribution you give it. This page shows each one, what triggers it, and whether it is exact or fitted.</p><p>The choice is driven by the squared coefficient of variation, <code>c² = var / mean²</code>, which measures dispersion relative to an exponential. An exponential has <code>c² = 1</code>, a tighter delay has <code>c² &lt; 1</code>, and a heavier-tailed one has <code>c² &gt; 1</code>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LoweredDistributions, Distributions</span></span></code></pre></div><h2 id="Exponential-delays-lower-to-a-two-state-CTMC" tabindex="-1">Exponential delays lower to a two-state CTMC <a class="header-anchor" href="#Exponential-delays-lower-to-a-two-state-CTMC" aria-label="Permalink to &quot;Exponential delays lower to a two-state CTMC {#Exponential-delays-lower-to-a-two-state-CTMC}&quot;">​</a></h2><p>An <code>Exponential</code> is memoryless, so no chain of compartments is needed: a single <code>on</code> state leaving to <code>absorbed</code> at the rate reproduces it exactly.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Exponential</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">CTMC continuous-time Markov chain</span></span>\n<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">  states: on, absorbed</span></span>\n<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">  on -&gt; absorbed @ rate 0.5</span></span></code></pre></div><h2 id="Under-and-equally-dispersed-delays-lower-to-an-ErlangChain" tabindex="-1">Under- and equally-dispersed delays lower to an <code>ErlangChain</code> <a class="header-anchor" href="#Under-and-equally-dispersed-delays-lower-to-an-ErlangChain" aria-label="Permalink to &quot;Under- and equally-dispersed delays lower to an `ErlangChain` {#Under-and-equally-dispersed-delays-lower-to-an-ErlangChain}&quot;">​</a></h2><p>When <code>c² ≤ 1</code> the delay is at least as tight as an exponential, so it is represented as compartments in series. A <code>Gamma</code> with integer shape is exactly that many compartments, so this lowering is exact rather than fitted.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ErlangChain(3 compartments)</span></span></code></pre></div><p>A non-integer shape still lowers to an <code>ErlangChain</code>, but now by matching the first two moments rather than exactly.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LogNormal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># c² ≈ 0.28 ≤ 1</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">ErlangChain(4 compartments)</span></span></code></pre></div><h2 id="Over-dispersed-delays-lower-to-a-branching-PhaseType" tabindex="-1">Over-dispersed delays lower to a branching <code>PhaseType</code> <a class="header-anchor" href="#Over-dispersed-delays-lower-to-a-branching-PhaseType" aria-label="Permalink to &quot;Over-dispersed delays lower to a branching `PhaseType` {#Over-dispersed-delays-lower-to-a-branching-PhaseType}&quot;">​</a></h2><p>When <code>c² &gt; 1</code> no chain in series can reproduce the spread, so the fit branches instead: a mixture over phases, matching the first two moments.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># c² = 2 &gt; 1</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">PhaseType(2 phases)</span></span></code></pre></div><h2 id="Asking-for-the-canonical-form-directly" tabindex="-1">Asking for the canonical form directly <a class="header-anchor" href="#Asking-for-the-canonical-form-directly" aria-label="Permalink to &quot;Asking for the canonical form directly {#Asking-for-the-canonical-form-directly}&quot;">​</a></h2><p>The three forms above are what <code>lower</code> picks for you, so its return type is a <code>Union</code> that only resolves once the value is known. Every representation also converts to one canonical <code>PhaseType(α, S)</code>: an initial distribution <code>α</code> over transient phases, and a sub-generator <code>S</code> whose row shortfalls are the exit rates to the absorbing state. This is the shape every backend extension consumes.</p><p>Passing <code>PhaseType</code> as a second argument returns that canonical form directly, in one step and with a single concrete return type. This is the form to differentiate through, and the one to reach for when the structure varies at runtime.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), PhaseType)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">PhaseType(3 phases)</span></span></code></pre></div><p>Because the return type no longer depends on the value, the over-dispersed case looks the same from the outside.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), PhaseType)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">PhaseType(2 phases)</span></span></code></pre></div><p>A fixed phase count is available too, which sidesteps the dispersion criterion entirely.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), PhaseType; phases </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">PhaseType(5 phases)</span></span></code></pre></div><h2 id="Where-Coxian-fits" tabindex="-1">Where <code>Coxian</code> fits <a class="header-anchor" href="#Where-Coxian-fits" aria-label="Permalink to &quot;Where `Coxian` fits {#Where-Coxian-fits}&quot;">​</a></h2><p><a href="/previews/PR110/lib/public#LoweredDistributions.Coxian"><code>Coxian</code></a> is a fourth representation the package carries, but <code>lower</code> never returns one. It is the intermediate hop used when converting an <code>ErlangChain</code> to its canonical form, and it is available by explicit conversion if you want a Coxian view of a chain.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Coxian</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">Coxian(3 phases)</span></span></code></pre></div><h2 id="Going-back" tabindex="-1">Going back <a class="header-anchor" href="#Going-back" aria-label="Permalink to &quot;Going back {#Going-back}&quot;">​</a></h2><p><code>lowering_to_distribution</code> reads a lowering back as a distribution. With one argument it returns the lowering&#39;s own law, exactly: a homogeneous chain is a <code>Gamma</code>, a single phase an <code>Exponential</code>, and anything else a <code>PhaseTypeDist</code> whose density is closed form.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lowering_to_distribution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">Distributions.Gamma{Float64}(α=3.0, θ=1.5)</span></span></code></pre></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lowering_to_distribution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">PhaseTypeDist(2 phases)</span></span></code></pre></div><p>The family a delay started as cannot be read back from a lowering. <code>lower</code> keeps only the mean and <code>c²</code>, so <code>LogNormal(0, 0.5)</code> and a moment-matched <code>Gamma</code> land on the same chain. Naming a target family as a second argument is the explicit request to project onto it.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lowering_to_distribution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lower</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LogNormal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)), LogNormal)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">Distributions.LogNormal{Float64}(μ=0.013428224342895118, σ=0.47238072707743883)</span></span></code></pre></div><p>That round trip is not the identity. The mean survives, but <code>lower</code> quantised <code>c²</code> onto the <code>1/k</code> grid on the way down, so the recovered variance sits on that grid too. <code>lowering_to_dist</code> is an alias if you prefer the shorter name.</p><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Input</th><th style="text-align:left;"><code>c²</code></th><th style="text-align:left;"><code>lower</code> returns</th><th style="text-align:left;">Exact or fitted</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Exponential</code></td><td style="text-align:left;"><code>= 1</code></td><td style="text-align:left;"><a href="/previews/PR110/lib/public#LoweredDistributions.CTMC"><code>CTMC</code></a></td><td style="text-align:left;">exact</td></tr><tr><td style="text-align:left;">integer-shape <code>Gamma</code></td><td style="text-align:left;"><code>≤ 1</code></td><td style="text-align:left;"><a href="/previews/PR110/lib/public#LoweredDistributions.ErlangChain"><code>ErlangChain</code></a></td><td style="text-align:left;">exact</td></tr><tr><td style="text-align:left;">other <code>c² ≤ 1</code> delays</td><td style="text-align:left;"><code>≤ 1</code></td><td style="text-align:left;"><a href="/previews/PR110/lib/public#LoweredDistributions.ErlangChain"><code>ErlangChain</code></a></td><td style="text-align:left;">two moments</td></tr><tr><td style="text-align:left;"><code>c² &gt; 1</code> delays</td><td style="text-align:left;"><code>&gt; 1</code></td><td style="text-align:left;"><a href="/previews/PR110/lib/public#LoweredDistributions.PhaseType"><code>PhaseType</code></a></td><td style="text-align:left;">two moments</td></tr></tbody></table><p><code>lower(dist, PhaseType)</code> returns the canonical <code>(α, S)</code> for any of these. <a href="/previews/PR110/lib/public#LoweredDistributions.Coxian"><code>Coxian</code></a> is reachable by conversion, not from <code>lower</code>.</p><p>See the <a href="/previews/PR110/getting-started/tutorials/lowering-backends#lowering-backends">lowering tutorial</a> for how faithfully each fit reproduces the density it came from, and for the backends that consume the canonical form.</p>',48)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
